#define BlockSize vec2(20,20)
#define seed 2564.12354

float hash12(vec2 p)
{
	p=p+seed;
	vec3 p3  = fract(vec3(p.xyx) * .1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}


float sdSegment( in vec2 p, in vec2 a, in vec2 b ) {
	 vec2 pa = p-a, ba = b-a; 
	 float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 ); 
	 return length( pa - ba*h ); 
}
float geometry(vec2 fc){
	vec2 blockCoord = floor(fc / BlockSize);
	vec2 blockPos = blockCoord * BlockSize;
	float hv = hash12(blockCoord.xx);
	float hh = hash12(blockCoord.yy);

	vec2 pt1Mult = hv>hh ? vec2(0.,.5) : vec2(.5,0);
	vec2 pt2Mult = hv>hh ? vec2(1.,.5) : vec2(.5,1);

	float d = sdSegment(fc,blockPos+BlockSize*pt1Mult,blockPos+BlockSize*pt2Mult);

	return d-length(BlockSize)*.05;  
}


void mainImage(out vec4 fragColor, in vec2 fragCoord) {

	float lines = geometry(fragCoord.xy+vec2(iTime)*vec2(90,30));
	fragColor = vec4(vec3(lines), 1.0);
}
